@SuppressWarnings("unchecked") public static List<Class<?>> loadClasses(URL url) throws IOException, IllegalArgumentException, SecurityException, ClassNotFoundException {
        JarFile jarFile = new JarFile(new File(url.getPath()));
        Set<String> entryNames = jarFile.getJarEntryNames();
        List<Class<?>> classes = new ArrayList<>();
        for (String entryName : entryNames) {
