public void generateGraph(Graph<V,E> target,Map<String,V> resultMap) {
int poolSize = target.vertexSet().size();
int numPartitions = resultMap.size();

// create a pool of "aliases" of each vertex in the graph
ArrayList<V> partitionAliases = new ArrayList<V>(poolSize);
for (V vertex : target.vertexSet()) {
    partitionAliases.add(vertex);
}

// move each vertex into the appropriate bin
for (Entry<String,V> entry : resultMap.entrySet()) {
    int partitionIndex = Integer.parseInt(entry.getKey().split(":")[1]) % numPartitions;
    V vertex = entry.getValue();
    target.addVertex(partitionAliases.get(partitionIndex));
    target.addEdge(vertex, partitionAliases.get(partitionIndex));
}

// move each edge into the appropriate bin
// note that we need to make sure to maintain the direction of the edges
for (E edge : target.edgeSet()) {
    int partitionIndex = Integer.parseInt(resultMap.get(target.getEdgeSource(edge).toString()).toString().split(":")[1]) % numPartitions;
    V destination = partitionAliases.get(partitionIndex);
    target.addEdge(destination, target.getEdgeTarget(edge));
    target.removeEdge(edge);
}
}

