    List<Pair<List<Pair<Integer, Integer>>, E>> globalSeparatorList = new ArrayList<>();

    // Iterate over the edges in the graph
    for (E edge : G.edgeSet()) {
        // Compute list of minimal separators for this edge
        List<Pair<Integer, Integer>> separators = computeMinimalSeparators(edge);
        // Construct a new Pair with the list of separators and the edge
        Pair<List<Pair<Integer, Integer>>, E> separatorPair = new Pair<>(separators, edge);
        // Add the separator pair to the global separator list
        globalSeparatorList.add(separatorPair);
    }

    return globalSeparatorList;
}

/**
 * Computes a list of minimal separators for a given edge in the graph.
 * @param edge the edge to compute the separators for
 * @return a list of minimal separators for the given edge
 */
private List<Pair<Integer, Integer>> computeMinimalSeparators(E edge) {
    List<Pair<Integer, Integer>> separators = new ArrayList<>();

    // Get the neighboring vertices of the edge
    Set<Integer> neighbors = G.neighborSetOf(edge);
    // Iterate over the neighbors of the edge
    for (Integer neighbor : neighbors) {
        // Compute the minimal separator for this neighbor
        Pair<Integer, Integer> separator = computeMinimalSeparator(edge, neighbor);
        // If the separator is not null, add it to the list of separators
        if (separator != null) {
            separators.add(separator);
        }
    }

    return separators;
}

/**
 * Computes the minimal separator for a given edge and its neighbor in the graph.
 * @param edge the edge to compute the separator for
 * @param neighbor the neighbor vertex to compute the separator for
 * @return the minimal separator for the given edge and neighbor, or null if no such separator exists
 */
private Pair<Integer, Integer> computeMinimalSeparator(E edge, int neighbor) {
    // Check if the edge and neighbor are adjacent
    if (!G.isAdjacent(edge, neighbor)) {
        return null;
    }

    // Compute the separator distance for the edge and neighbor
    int separatorDistance = getSeparatorDistance(edge, neighbor);
    // If the distance is zero, no minimal separator exists
    if (separatorDistance == 0) {
        return null;
    }

    // Compute the separator for the edge and neighbor
    Pair<Integer, Integer> separator = new Pair<>(getSeparator(edge, neighbor), separatorDistance);
    return separator;
}

/**
 * Computes the separator for a given edge and its neighbor in the graph.
 * @param edge the edge to compute the separator for
 * @param neighbor the neighbor vertex to compute the separator for
 * @return the separator for the given edge and neighbor
 */
private Pair<Integer, Integer> getSeparator(E edge, int neighbor) {
    // Compute the distance from the edge to the neighbor
    int distance = G.getDistance(edge, neighbor);
    // Compute the separator distance for the edge and neighbor
    int separatorDistance = getSeparatorDistance(edge, neighbor);
    // Compute the separator
    return new Pair<>(neighbor - distance + separatorDistance, neighbor + distance - separatorDistance);
}

/**
 * Computes the separator distance for a given edge and its neighbor in the graph.
 * @param edge the edge to compute the separator distance for
 * @param neighbor the neighbor vertex to compute the separator distance for
 * @return the separator distance for the given edge and neighbor
 */
private int getSeparatorDistance(E edge, int neighbor) {
    // Check if the edge and neighbor are adjacent
    if (!G.isAdjacent(edge, neighbor)) {
        return 0;
    }

    // Compute the distance from the edge to the neighbor
    int distance = G.getDistance(edge, neighbor);
    // Compute the separator distance
    return distance / 2;
}

